INSERT INTO x1(content) VALUES('''Twas Mulga Bill, from Eaglehawk, that sought his own abode,'); INSERT INTO x1(content) VALUES('That perched above Dead Man''s Creek, beside the mountain road.'); INSERT INTO x1(content) VALUES('He turned the cycle down the hill and mounted for the fray,'); INSERT INTO x1(content) VALUES('But ''ere he''d gone a dozen yards it bolted clean away.'); INSERT INTO x1(content) VALUES('It left the track, and through the trees, just like a silver steak,'); INSERT INTO x1(content) VALUES('It whistled down the awful slope towards the Dead Man''s Creek.'); INSERT INTO x1(content) VALUES('It shaved a stump by half an inch, it dodged a big white-box:'); INSERT INTO x1(content) VALUES('The very wallaroos in fright went scrambling up the rocks,'); INSERT INTO x1(content) VALUES('The wombats hiding in their caves dug deeper underground,'); INSERT INTO x1(content) VALUES('As Mulga Bill, as white as chalk, sat tight to every bound.'); INSERT INTO x1(content) VALUES('It struck a stone and gave a spring that cleared a fallen tree,'); INSERT INTO x1(content) VALUES('It raced beside a precipice as close as close could be;'); INSERT INTO x1(content) VALUES('And then as Mulga Bill let out one last despairing shriek'); INSERT INTO x1(content) VALUES('It made a leap of twenty feet into the Dead Man''s Creek.'); INSERT INTO x1(content) VALUES('It shaved a stump by half an inch, it dodged a big white-box:'); INSERT INTO x1(content) VALUES('The very wallaroos in fright went scrambling up the rocks,'); INSERT INTO x1(content) VALUES('The wombats hiding in their caves dug deeper underground,');